-- Notifications v1 (ADR-0062): the admin's notices for the rep app, their products and reads, and
-- the notifications addressed to one user (a rep's sold order). Generated by drizzle-kit, then by
-- hand: the REVOKEs and column grants below.
CREATE TABLE "app_notice_products" (
	"notice_id" bigint NOT NULL,
	"product_id" bigint NOT NULL,
	"position" smallint NOT NULL,
	CONSTRAINT "app_notice_products_notice_id_product_id_pk" PRIMARY KEY("notice_id","product_id"),
	CONSTRAINT "app_notice_products_position" UNIQUE("notice_id","position"),
	CONSTRAINT "app_notice_products_position_range" CHECK ("app_notice_products"."position" BETWEEN 1 AND 20)
);
--> statement-breakpoint
CREATE TABLE "app_notice_reads" (
	"notice_id" bigint NOT NULL,
	"user_id" bigint NOT NULL,
	"read_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "app_notice_reads_notice_id_user_id_pk" PRIMARY KEY("notice_id","user_id")
);
--> statement-breakpoint
CREATE TABLE "app_notices" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "app_notices_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"kind" text NOT NULL,
	"title" text NOT NULL,
	"body" text NOT NULL,
	"image_file_id" bigint,
	"popup" boolean DEFAULT false NOT NULL,
	"valid_from" date NOT NULL,
	"valid_to" date,
	"created_by" bigint NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"withdrawn_at" timestamp with time zone,
	"withdrawn_by" bigint,
	CONSTRAINT "app_notices_kind" CHECK ("app_notices"."kind" IN ('PROMOTION', 'PRICE_DROP', 'NEW_PRODUCT', 'NEWS')),
	CONSTRAINT "app_notices_title" CHECK (length(btrim("app_notices"."title")) BETWEEN 1 AND 80),
	CONSTRAINT "app_notices_body" CHECK (length(btrim("app_notices"."body")) BETWEEN 1 AND 1000),
	CONSTRAINT "app_notices_dates" CHECK ("app_notices"."valid_to" IS NULL OR "app_notices"."valid_to" > "app_notices"."valid_from"),
	CONSTRAINT "app_notices_withdrawn" CHECK (("app_notices"."withdrawn_at" IS NULL) = ("app_notices"."withdrawn_by" IS NULL))
);
--> statement-breakpoint
CREATE TABLE "user_notifications" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "user_notifications_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"user_id" bigint NOT NULL,
	"kind" text NOT NULL,
	"order_id" bigint,
	"payload" jsonb NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"read_at" timestamp with time zone,
	CONSTRAINT "user_notifications_order" UNIQUE("kind","order_id"),
	CONSTRAINT "user_notifications_kind" CHECK ("user_notifications"."kind" IN ('ORDER_SOLD')),
	CONSTRAINT "user_notifications_order_required" CHECK ("user_notifications"."kind" <> 'ORDER_SOLD' OR "user_notifications"."order_id" IS NOT NULL)
);
--> statement-breakpoint
ALTER TABLE "app_notice_products" ADD CONSTRAINT "app_notice_products_notice_id_app_notices_id_fk" FOREIGN KEY ("notice_id") REFERENCES "public"."app_notices"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "app_notice_products" ADD CONSTRAINT "app_notice_products_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "public"."products"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "app_notice_reads" ADD CONSTRAINT "app_notice_reads_notice_id_app_notices_id_fk" FOREIGN KEY ("notice_id") REFERENCES "public"."app_notices"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "app_notice_reads" ADD CONSTRAINT "app_notice_reads_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "app_notices" ADD CONSTRAINT "app_notices_image_file_id_files_id_fk" FOREIGN KEY ("image_file_id") REFERENCES "public"."files"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "app_notices" ADD CONSTRAINT "app_notices_created_by_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "app_notices" ADD CONSTRAINT "app_notices_withdrawn_by_users_id_fk" FOREIGN KEY ("withdrawn_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "user_notifications" ADD CONSTRAINT "user_notifications_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "user_notifications" ADD CONSTRAINT "user_notifications_order_id_sales_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."sales_orders"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "app_notices_image" ON "app_notices" USING btree ("image_file_id");--> statement-breakpoint
CREATE INDEX "app_notices_live_idx" ON "app_notices" USING btree ("valid_from","id") WHERE "app_notices"."withdrawn_at" IS NULL;--> statement-breakpoint
CREATE INDEX "user_notifications_user_idx" ON "user_notifications" USING btree ("user_id","id");--> statement-breakpoint
CREATE INDEX "user_notifications_unread_idx" ON "user_notifications" USING btree ("user_id") WHERE "user_notifications"."read_at" IS NULL;

-- Hand-written: a sent notice is never edited or deleted (ADR-0062 #1); app may only withdraw it.
-- Its products and the reads are written once. (SELECT … FOR UPDATE needs the column grant.)
REVOKE UPDATE, DELETE, TRUNCATE ON "app_notices" FROM app;--> statement-breakpoint
GRANT UPDATE ("withdrawn_at", "withdrawn_by") ON "app_notices" TO app;--> statement-breakpoint
REVOKE UPDATE, DELETE, TRUNCATE ON "app_notice_products", "app_notice_reads" FROM app;--> statement-breakpoint

-- Hand-written: a notification stays; only the moment it was read is set.
REVOKE UPDATE, DELETE, TRUNCATE ON "user_notifications" FROM app;--> statement-breakpoint
GRANT UPDATE ("read_at") ON "user_notifications" TO app;
